let azRarity='all',azSort='level';
function azCandidateMeta(button){const key=button.dataset.candidate,g=tavRec(key);return {button,key,level:hLevel(key),rarity:g.r,stars:g.k,power:azSort==='power'?kPower(key):0};}
function azCandidateCompare(a,b){
  if(azSort==='power')return b.power-a.power||b.level-a.level||b.rarity-a.rarity||b.stars-a.stars||a.key.localeCompare(b.key);
  if(azSort==='rarity')return b.rarity-a.rarity||b.stars-a.stars||b.level-a.level||a.key.localeCompare(b.key);
  return b.level-a.level||b.rarity-a.rarity||b.stars-a.stars||a.key.localeCompare(b.key);
}
function azCandidates(){
  azCandidatesBase();
  const list=azPick.querySelector('.az-candidates'),rows=Array.from(list.querySelectorAll('[data-candidate]')).map(azCandidateMeta).filter(row=>azRarity==='all'||row.rarity===Number(azRarity)).sort(azCandidateCompare);
  list.replaceChildren();
  for(const row of rows){
    const b=row.button,g=tavRec(row.key),rarity=RAR[row.rarity];
    b.style.setProperty('border','2px solid '+rarity.c,'important');b.style.setProperty('--rc',rarity.c);
    const label=document.createElement('small');label.className='az-picker-rarity';label.style.color=rarity.c;label.textContent=rarity.n+' · +'+Math.round(tavBonus(g)*100)+'% к характеристикам';b.append(label);
    b.setAttribute('aria-label',heroName(row.key)+', '+row.level+' уровень, '+rarity.n+', '+row.stars+' звёзд');list.append(b);
  }
  if(!rows.length)list.textContent='Нет свободных полученных спутников под выбранные фильтры.';
  const controls=document.createElement('div');controls.className='az-buttons';
  function selectControl(title,data,entries,current,change){const label=document.createElement('label'),select=document.createElement('select');label.append(title+' ');select.setAttribute('aria-label',title);select.setAttribute(data,'');for(const [value,text] of entries){const option=document.createElement('option');option.value=String(value);option.textContent=text;select.append(option);}select.value=current;select.onchange=()=>{change(select.value);azCandidates();azPick.querySelector('['+data+']')?.focus();};label.append(select);controls.append(label);}
  selectControl('Редкость спутника','data-picker-rarity',[['all','Любая'],...RAR.map((r,i)=>[String(i),r.n])],azRarity,value=>{azRarity=value;});
  selectControl('Сортировка спутников','data-picker-sort',[['level','Уровень, редкость, звёзды'],['rarity','Редкость, звёзды, уровень'],['power','Оценка силы']],azSort,value=>{azSort=value;});
  list.before(controls);
}
